def find_middle(input_string: str) -> int:
    if not any(char.isdigit() for char in input_string):
        return -1

    product_str = ''.join(char for char in input_string if char.isdigit())
    product = int(product_str)
    product_str = str(product)
    len_product_str = len(product_str)

    if len_product_str % 2 == 1:
        return int(product_str[len_product_str // 2])
    else:
        return int(product_str[len_product_str // 2 - 1:len_product_str // 2 + 1].lstrip('0'))
